from __future__ import annotations

from pathlib import Path
import base64
import hashlib
import re
import zlib

ROOT = Path(__file__).resolve().parent
PAYLOADS = {'dashboard/src/pages/DispatchBoard.tsx': '', 'dashboard/src/components/dispatch/PendingRoutesTable.tsx': '', 'dashboard/src/components/dispatch/RouteManagementModal.tsx': '', 'dashboard/src/components/dispatch/AdjustInventoryModal.tsx': '', 'dashboard/src/components/dispatch/TransfersRadarModal.tsx': ''}
PARENT_INPUT_SHA256 = '2b44cf3a499254d16f1c2842be62390f5634550c589a5c7fabf70d0293e2861c'
V3_MARKER = "DASHBOARD_DISPATCH_ROUTE_CONTRACT_V3"
ACTIVE_OLD = '            "sessionEnded": session_ended \n        })'
ACTIVE_NEW = '            "sessionEnded": session_ended,\n            "sessionBound": r.work_session_id is not None\n        })'


def fail(message: str) -> None:
    raise SystemExit(f"PATCH_ABORTED: {message}")


def normalize(text: str) -> str:
    return text.replace("\r\n", "\n")


def sha256_norm(text: str) -> str:
    return hashlib.sha256(normalize(text).encode("utf-8")).hexdigest()


def decode_payload(path: str) -> str:
    return zlib.decompress(base64.b64decode(PAYLOADS[path])).decode("utf-8")


def require_file(rel: str) -> Path:
    path = ROOT / rel
    if not path.exists():
        fail(f"Missing file: {rel}")
    return path


def write_preserving_newlines(path: Path, content_lf: str) -> None:
    current_raw = path.read_text(encoding="utf-8")
    newline = "\r\n" if "\r\n" in current_raw else "\n"
    content = content_lf if newline == "\n" else content_lf.replace("\n", "\r\n")
    path.write_text(content, encoding="utf-8", newline="")


# 1) Exact reviewed DispatchBoard state.
parent_rel = "dashboard/src/pages/DispatchBoard.tsx"
parent = require_file(parent_rel)
parent_now = parent.read_text(encoding="utf-8")
parent_target = decode_payload(parent_rel)

if sha256_norm(parent_now) == sha256_norm(parent_target):
    print("UNCHANGED=dashboard/src/pages/DispatchBoard.tsx")
elif sha256_norm(parent_now) == PARENT_INPUT_SHA256:
    write_preserving_newlines(parent, parent_target)
    print("PATCHED=dashboard/src/pages/DispatchBoard.tsx")
else:
    fail(
        "DispatchBoard.tsx differs from the exact reviewed file. "
        f"Current normalized SHA256={sha256_norm(parent_now)}"
    )


# 2) Route child files.
child_guards = {
    "dashboard/src/components/dispatch/PendingRoutesTable.tsx": [
        "إغلاق وتصفير المنطقة ✅",
        "🛑 إيقاف وسحب",
        "onOpenRouteModal",
    ],
    "dashboard/src/components/dispatch/RouteManagementModal.tsx": [
        "جرد الحمولة الحالي",
        "disabled={false}",
        "الكمية (حبة)",
    ],
    "dashboard/src/components/dispatch/AdjustInventoryModal.tsx": [
        "JSON.stringify({ deltas: payloadDeltas })",
        "catch (error: any)",
        "fetchInventory();",
    ],
    "dashboard/src/components/dispatch/TransfersRadarModal.tsx": [
        "icon: any",
        "created_at: string;",
        "'pending' | 'accepted' | 'rejected'",
    ],
}

for rel, guards in child_guards.items():
    path = require_file(rel)
    current = normalize(path.read_text(encoding="utf-8"))
    target = decode_payload(rel)

    if V3_MARKER in current:
        if current != normalize(target):
            fail(f"{rel} contains V3 marker but differs from expected V3 content.")
        print(f"UNCHANGED={rel}")
        continue

    missing = [marker for marker in guards if marker not in current]
    if missing:
        fail(f"{rel} baseline mismatch; missing markers: {missing}")

    write_preserving_newlines(path, target)
    print(f"PATCHED={rel}")


# 3) Shared route type.
types_path = require_file("dashboard/src/types/dispatch.ts")
types = normalize(types_path.read_text(encoding="utf-8"))

if "  sessionBound: boolean;\n" not in types:
    old = "  sessionEnded: boolean;\n"
    if types.count(old) != 1:
        fail("PendingRoute sessionEnded contract not found exactly once.")
    types = types.replace(old, old + "  sessionBound: boolean;\n", 1)
    print("PATCHED=dashboard/src/types/dispatch.ts:sessionBound")
else:
    print("UNCHANGED=dashboard/src/types/dispatch.ts:sessionBound")

if "  frequency: string;\n" in types:
    types = types.replace("  frequency: string;\n", "  frequency?: string;\n", 1)
if "  visitDay: string;\n" in types:
    types = types.replace("  visitDay: string;\n", "  visitDay?: string;\n", 1)

write_preserving_newlines(types_path, types)


# 4) Additive backend read contract only: sessionBound.
schemas_path = require_file("wa_backend/schemas.py")
schemas = normalize(schemas_path.read_text(encoding="utf-8"))

if "    sessionBound: bool\n" not in schemas:
    old = "    sessionEnded: bool\n"
    if schemas.count(old) != 1:
        fail("ActiveRouteResponse sessionEnded contract not found exactly once.")
    schemas = schemas.replace(old, old + "    sessionBound: bool\n", 1)
    print("PATCHED=wa_backend/schemas.py:sessionBound")
else:
    print("UNCHANGED=wa_backend/schemas.py:sessionBound")

write_preserving_newlines(schemas_path, schemas)


dispatch_path = require_file("wa_backend/api/dispatch.py")
dispatch = normalize(dispatch_path.read_text(encoding="utf-8"))

if '"sessionBound": r.work_session_id is not None' not in dispatch:
    if dispatch.count(ACTIVE_OLD) != 1:
        fail("active_routes response block not found exactly once.")
    dispatch = dispatch.replace(ACTIVE_OLD, ACTIVE_NEW, 1)
    print("PATCHED=wa_backend/api/dispatch.py:sessionBound")
else:
    print("UNCHANGED=wa_backend/api/dispatch.py:sessionBound")

write_preserving_newlines(dispatch_path, dispatch)


# 5) Static gates.
board = normalize(parent.read_text(encoding="utf-8"))
pending = normalize(require_file("dashboard/src/components/dispatch/PendingRoutesTable.tsx").read_text(encoding="utf-8"))
route_modal = normalize(require_file("dashboard/src/components/dispatch/RouteManagementModal.tsx").read_text(encoding="utf-8"))
adjust = normalize(require_file("dashboard/src/components/dispatch/AdjustInventoryModal.tsx").read_text(encoding="utf-8"))
radar = normalize(require_file("dashboard/src/components/dispatch/TransfersRadarModal.tsx").read_text(encoding="utf-8"))
types = normalize(types_path.read_text(encoding="utf-8"))
schemas = normalize(schemas_path.read_text(encoding="utf-8"))
dispatch = normalize(dispatch_path.read_text(encoding="utf-8"))

shops_start = dispatch.find('@router.get("/dispatch/shops"')
shops_end = dispatch.find("# PATCH: DISPATCH_CONCURRENCY_EMERGENCY_INTEGRITY", shops_start)
if shops_start == -1 or shops_end == -1:
    fail("Could not locate tenant-scoped /dispatch/shops block.")
shops_block = dispatch[shops_start:shops_end]

checks = {
    "NO_FRONTEND_COMPANY_ID": re.search(r"\bcompany_?id\b", board, re.I) is None,
    "NO_OLD_INVENTORY_ENGINE": all(
        marker not in board + pending + route_modal + adjust + radar
        for marker in ("MainWarehouse", "WarehouseLedger")
    ),
    "SOURCE_WAREHOUSE_EXPLICIT": (
        'label="مستودع المصدر"' in board
        and 'source_location_id: Number(selectedSourceWarehouseId)' in board
        and '(options[0]?.id || "")' not in board
    ),
    "WAREHOUSE_STATUS_SCOPED": (
        '/warehouse/status?location_id=${encodeURIComponent(selectedSourceWarehouseId)}' in board
        and 'authenticatedFetch("/warehouse/status"' not in board
    ),
    "VEHICLE_INVENTORY_FRESHNESS": (
        "vehicleInventoryLoadedForId" in board
        and "vehicleInventoryReloadKey" in board
    ),
    "WORKSESSION_IDENTITY_GUARD": (
        "activeRoute.sessionBound" in board
        and "route.sessionBound" in pending
        and "identityLocked" in route_modal
    ),
    "NO_CLOSE_EQUALS_ZERO": (
        "تصفير السيارة" not in board
        and "إغلاق وتصفير" not in pending
    ),
    "WAITING_DOES_NOT_CLEAR_ROUTE_ASSETS": (
        'status: "waiting", driverId: "", vehicleId: ""' not in board
    ),
    "SHORTAGE_REQUEST_EXTRA_FORBID_SAFE": (
        "productId: Number(item.productId),\n      productName:" not in board
    ),
    "SHOP_OPTIONALS_MATCH_BACKEND": (
        "!shopForm.phone.trim()" not in board
        and "!shopForm.mapLink.trim()" not in board
    ),
    "ADJUST_IDEMPOTENCY": (
        "request_id: requestId" in adjust
        and "crypto.randomUUID()" in adjust
        and "catch (error: any)" not in adjust
    ),
    "RADAR_FULL_TRANSFER_CONTRACT": (
        "cancelled:" in radar
        and "delta_packs" in radar
        and "created_at: string;" not in radar
        and "icon: any" not in radar
    ),
    "ROUTE_QUANTITY_UNIT_CARTONS": "الكمية المستهدفة (كرتونة)" in route_modal,
    "ACTIVE_ROUTE_SESSION_BOUND_TYPE": "sessionBound: boolean;" in types,
    "ACTIVE_ROUTE_SESSION_BOUND_SCHEMA": "sessionBound: bool" in schemas,
    "ACTIVE_ROUTE_SESSION_BOUND_RESPONSE": '"sessionBound": r.work_session_id is not None' in dispatch,
    "ARCHIVED_SHOPS_STILL_TENANT_SCOPED": (
        "Shop.company_id == current_admin.company_id" in shops_block
        and "Shop.is_archived == False" not in shops_block
    ),
    "SHORTAGE_PRODUCT_ID_READ_CONTRACT": (
        '"productId": str(s.product_variant_id),' in dispatch
        and "productId: str" in schemas
    ),
}

failed = [name for name, ok in checks.items() if not ok]
if failed:
    fail(f"Static verification failed: {failed}")

print("DISPATCH_ROUTE_SOURCE_WAREHOUSE=OK")
print("DISPATCH_ROUTE_WORKSESSION_IDENTITY=OK")
print("DISPATCH_ROUTE_INVENTORY_FRESHNESS=OK")
print("DISPATCH_ADJUST_IDEMPOTENCY=OK")
print("DISPATCH_TRANSFER_RADAR_CONTRACT=OK")
print("DISPATCH_TENANT_SCOPE=OK")
print("DASHBOARD_DISPATCH_ROUTE_CONTRACT_V3=OK")
